one.code:
def oneAtom(): Theory.Descriptor = {
    // Position 0 is a file; position 1 is the file it imports.
    atoms = { relation = Atom.Imports, subject = 0, object = 1 } :: Nil,
    // An empty list of position pairs that must be different.
    denied = Nil,
    // Return positions 0 and 1. Read :: as "followed by"; Nil ends the list.
    outputs = 0 :: 1 :: Nil
}

two.code:
def twoAtoms(): Theory.Descriptor = {
    // Two Imports rows must agree on position 1: their shared target.
    atoms = { relation = Atom.Imports, subject = 0, object = 1 }
         :: { relation = Atom.Imports, subject = 2, object = 1 } :: Nil,
    // No inequality: positions 0 and 2 may hold the SAME file.
    denied = Nil,
    // Return the two consumers; do not return the shared target.
    outputs = 0 :: 2 :: Nil
}

three.code:
def threeAtoms(): Theory.Descriptor = {
    // File 0 defines caller 1; caller 1 calls symbol 2; file 3 contains 2.
    atoms = { relation = Atom.Defines, subject = 0, object = 1 }
         :: { relation = Atom.Calls, subject = 1, object = 2 }
         :: { relation = Atom.DefinedIn, subject = 2, object = 3 } :: Nil,
    denied = Nil,
    // Keep the files at the ends; the intermediate symbols are not returned.
    outputs = 0 :: 3 :: Nil
}

binding.code:
// shape 0>1;2>1
Binding(c, w, e0, e1, e2, e0) :-
    Desc(c, shape, r0, r1, r2, _, neq0, neq1, _, _),
    Edge(w, r0, e0, e1),
    Edge(w, r1, e2, e1),
    if (shape == "0>1;2>1"),
    if (neq0 != 0 or neq1 != 1 or e0 != e1),
    if (neq0 != 0 or neq1 != 2 or e0 != e2),
    if (neq0 != 1 or neq1 != 2 or e1 != e2).

bindingNotes.code:
// shape 0>1;2>1
// Record one match. c = question ID; w = source world.
// e0, e1, e2 are the values filling positions 0, 1, 2.
// The last e0 fills an unused fourth slot in the fixed row format.
Binding(c, w, e0, e1, e2, e0) :-
// Read the recipe for question c: shape, relations, inequality, outputs.
// _ means this line does not need that column’s value.
Desc(c, shape, r0, r1, r2, _, neq0, neq1, _, _),
// Find a first edge in world w, using relationship r0: e0 -> e1.
Edge(w, r0, e0, e1),
// Find a second edge in the SAME world, using r1: e2 -> e1.
// Repeating e1 makes the two edges share their target.
Edge(w, r1, e2, e1),
// Use this rule only for the shared-target wiring.
if (shape == "0>1;2>1"),
// Enforce each optional "these two positions must differ" check.
// A test passes when this is not the requested pair, OR the values differ.
// In the frozen 72-question family no pair is required to differ.
if (neq0 != 0 or neq1 != 1 or e0 != e1),
if (neq0 != 0 or neq1 != 2 or e0 != e2),
if (neq0 != 1 or neq1 != 2 or e1 != e2).
